questionvariables.text:
/* Shared Question Bank Place Value, Rounding and Standard Form PVRS-02
Foundation task: round a whole number to a specified place value.
This question is curriculum-independent. */
/* Choose one of three rounding places: 1 = nearest ten 2 = nearest hundred 3 = nearest thousand */
place_choice: rand_with_prohib(1,3,[]);
/* Resolve place value. */
place_value: if place_choice=1 then 10 elseif place_choice=2 then 100 else 1000;
/* Generate a six-digit candidate.
Then ensure the digit immediately to the right of the rounding place is at least 5.
This guarantees that correct rounding requires rounding upward, so truncation is always a distinguishable misconception. */
raw_number: rand_with_prohib( 100000, 998999, [] );
remainder: mod( raw_number, place_value );
number: if remainder < place_value/2 then raw_number + place_value/2 - remainder else raw_number;
/* Display label. */
place_name: if place_choice=1 then "ten" elseif place_choice=2 then "hundred" else "thousand";
/* Teacher answer.
Use explicit half-up rounding so a digit of 5 always rounds upward, matching the school rounding convention. */
answer: floor( ( number + place_value/2 ) / place_value ) * place_value;
/* Target misconception: learner truncates instead of rounding. */
wrong_truncate: floor(number/place_value) *place_value;
